    for p in sorted(R.glob('*.json.sha256')):
        target = R / p.name.removesuffix('.sha256')
        ok = sha(target) == p.read_text().split()[0]
        frozen.append({'path': target.name, 'sha256': sha(target), 'intact': ok})
        if not ok:
            raise ArithmeticError('Frozen artifact changed: ' + target.name)
